def main():
    conn = sqlite3.connect(DB)
    ing = KBIngestor(conn, batch_size=20)
    n_ok = 0
    for eid, title, src, content in E:
        ok, why = ing.insert(
            entry_id=f'{eid}|mingxiang|b11',
            module='mingxiang', title=title, content=content, category='mingxiang',
            keywords='["命相同参","玉管照神局","月波洞中记","批注"]',
            src_id=src, domain='mingli', trust=0.85,
            source='kimi-distill-mingxiang-b11-20261009')
        n_ok += ok
        print(eid, ok, why)
    ing.commit()
    print(f'命相名赋第十一批: {n_ok}/{len(E)} 入库')
    conn.close()

if __name__ == '__main__':
    main()
